/* ===== State (local storage only, wrapped in try/catch) ===== */
let S={profile:null,tasks:[],attempts:[],cards:{},notes:[],bank:[]};
const ME=(()=>{const a=sess();return a=='_guest'||users()[a]?a:'_guest'})(),DK=ME=='_guest'?'ssh_v1':'ssh_u_'+ME;try{const r=ME?localStorage.getItem(DK):null;if(r)S=Object.assign(S,clean(JSON.parse(r)))}catch(e){}
S.tasks.forEach(t=>{if(!t.date)t.date=t.due||iso(new Date());if(!t.dur)t.dur=45;if(t.time===undefined)t.time=''});
const save=()=>{if(!ME)return;try{localStorage.setItem(DK,JSON.stringify(S))}catch(e){}};
function iso(d){return d.toLocaleDateString('en-CA')}
