G(12,[[80,2],[100,3],[64,3],[200,4],[48,4],[120,2]],(n,k)=>`একটি তেজস্ক্রিয় পদার্থের ${n} g থেকে ${k}টি অর্ধায়ু পরে কত g অবশিষ্ট থাকবে?`,(n,k)=>n/Math.pow(2,k),' g');
const GT={AND:(a,b)=>a&b,OR:(a,b)=>a|b,NAND:(a,b)=>1-(a&b),NOR:(a,b)=>1-(a|b),XOR:(a,b)=>a^b};
